void testSortBy1() {
  // todo: other argument checks
  ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict{
      {std::string("id"), std::string("sampleexchange")},
  });
  ccxt::any arr = ccxt::list{ccxt::dict{
                                 {std::string("x"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             }};
  ccxt::any newArray = exchange.sortBy(arr, std::string("x"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), newArray,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 0},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 5},
                             }});
  ccxt::any newArrayDescending = exchange.sortBy(arr, std::string("x"), true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"),
                  newArrayDescending,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                             }});
  ccxt::any emptyArray = exchange.sortBy(ccxt::list{}, std::string("x"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), emptyArray,
                  ccxt::list{});
  // regression: keys crossing a digit-count boundary must sort numerically, a
  // lexicographic comparison yields 1, 10, 2 .. 9
  ccxt::any arrTwoDigits = ccxt::list{ccxt::dict{
                                          {std::string("x"), 10},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 1},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 3},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 7},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 2},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 9},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 5},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 8},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 4},
                                      },
                                      ccxt::dict{
                                          {std::string("x"), 6},
                                      }};
  ccxt::any sortedTwoDigits = exchange.sortBy(arrTwoDigits, std::string("x"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), sortedTwoDigits,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 6},
                             },
                             ccxt::dict{
                                 {std::string("x"), 7},
                             },
                             ccxt::dict{
                                 {std::string("x"), 8},
                             },
                             ccxt::dict{
                                 {std::string("x"), 9},
                             },
                             ccxt::dict{
                                 {std::string("x"), 10},
                             }});
  // immutability - original array should not be modified (ascending)
  ccxt::any original = ccxt::list{ccxt::dict{
                                      {std::string("x"), 5},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 2},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 4},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 0},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 1},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 3},
                                  }};
  exchange.sortBy(original, std::string("x"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), original,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             }});
  // immutability - original array should not be modified (descending)
  ccxt::any originalDescending = ccxt::list{ccxt::dict{
                                                {std::string("x"), 5},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 2},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 4},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 0},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 1},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 3},
                                            }};
  exchange.sortBy(originalDescending, std::string("x"), true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"),
                  originalDescending,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                             }});
  // immutability - array rows (orderbook-style numeric keys) should not be
  // modified
  ccxt::any originalRows = ccxt::list{
      ccxt::list{3000.5, 1}, ccxt::list{2900.5, 2}, ccxt::list{2950.5, 3}};
  exchange.sortBy(originalRows, 0);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), originalRows,
                  ccxt::list{ccxt::list{3000.5, 1}, ccxt::list{2900.5, 2},
                             ccxt::list{2950.5, 3}});
  exchange.sortBy(originalRows, 0, true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy"), originalRows,
                  ccxt::list{ccxt::list{3000.5, 1}, ccxt::list{2900.5, 2},
                             ccxt::list{2950.5, 3}});
}
void testSortBy2() {
  ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict{
      {std::string("id"), std::string("sampleexchange")},
  });
  // sort ascending by key1, then key2 (key1 values are all distinct here)
  ccxt::any arr = ccxt::list{ccxt::dict{
                                 {std::string("x"), 3},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                                 {std::string("y"), 4},
                             }};
  ccxt::any sorted = exchange.sortBy2(arr, std::string("x"), std::string("y"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"), sorted,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 0},
                                 {std::string("y"), 4},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 3},
                                 {std::string("y"), 1},
                             }});
  // sort descending by key1
  ccxt::any arr2 = ccxt::list{ccxt::dict{
                                  {std::string("x"), 3},
                                  {std::string("y"), 1},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 2},
                              },
                              ccxt::dict{
                                  {std::string("x"), 2},
                                  {std::string("y"), 3},
                              },
                              ccxt::dict{
                                  {std::string("x"), 0},
                                  {std::string("y"), 4},
                              }};
  ccxt::any sortedDescending =
      exchange.sortBy2(arr2, std::string("x"), std::string("y"), true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"),
                  sortedDescending,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 3},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                                 {std::string("y"), 4},
                             }});
  // when key1 values are equal, sort by key2 ascending
  ccxt::any arr3 = ccxt::list{ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 5},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 2},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 9},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 1},
                              }};
  ccxt::any sortedByKey2 =
      exchange.sortBy2(arr3, std::string("x"), std::string("y"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"), sortedByKey2,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 9},
                             }});
  // when key1 values are equal, sort by key2 descending
  ccxt::any arr4 = ccxt::list{ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 5},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 2},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 9},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 1},
                              }};
  ccxt::any sortedByKey2Descending =
      exchange.sortBy2(arr4, std::string("x"), std::string("y"), true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"),
                  sortedByKey2Descending,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 9},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 1},
                             }});
  // mixed: sort by key1 first, then key2 as tiebreaker
  ccxt::any arr5 = ccxt::list{ccxt::dict{
                                  {std::string("x"), 2},
                                  {std::string("y"), 3},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 5},
                              },
                              ccxt::dict{
                                  {std::string("x"), 2},
                                  {std::string("y"), 1},
                              },
                              ccxt::dict{
                                  {std::string("x"), 1},
                                  {std::string("y"), 2},
                              },
                              ccxt::dict{
                                  {std::string("x"), 2},
                                  {std::string("y"), 2},
                              }};
  ccxt::any sortedMixed =
      exchange.sortBy2(arr5, std::string("x"), std::string("y"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"), sortedMixed,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 5},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             }});
  // empty array
  ccxt::any emptyArray =
      exchange.sortBy2(ccxt::list{}, std::string("x"), std::string("y"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"), emptyArray,
                  ccxt::list{});
  // immutability - original array should not be modified (ascending)
  ccxt::any original = ccxt::list{ccxt::dict{
                                      {std::string("x"), 3},
                                      {std::string("y"), 1},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 1},
                                      {std::string("y"), 2},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 2},
                                      {std::string("y"), 3},
                                  },
                                  ccxt::dict{
                                      {std::string("x"), 0},
                                      {std::string("y"), 4},
                                  }};
  exchange.sortBy2(original, std::string("x"), std::string("y"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"), original,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 3},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                                 {std::string("y"), 4},
                             }});
  // immutability - original array should not be modified (descending)
  ccxt::any originalDescending = ccxt::list{ccxt::dict{
                                                {std::string("x"), 3},
                                                {std::string("y"), 1},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 1},
                                                {std::string("y"), 2},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 2},
                                                {std::string("y"), 3},
                                            },
                                            ccxt::dict{
                                                {std::string("x"), 0},
                                                {std::string("y"), 4},
                                            }};
  exchange.sortBy2(originalDescending, std::string("x"), std::string("y"),
                   true);
  assertDeepEqual(exchange, ccxt::any{}, std::string("sortBy2"),
                  originalDescending,
                  ccxt::list{ccxt::dict{
                                 {std::string("x"), 3},
                                 {std::string("y"), 1},
                             },
                             ccxt::dict{
                                 {std::string("x"), 1},
                                 {std::string("y"), 2},
                             },
                             ccxt::dict{
                                 {std::string("x"), 2},
                                 {std::string("y"), 3},
                             },
                             ccxt::dict{
                                 {std::string("x"), 0},
                                 {std::string("y"), 4},
                             }});
}
void testSortBy() {
  testSortBy1();
  testSortBy2();
}
